1	import type { Metadata } from "next";
2	import { cookies } from "next/headers";
3	import { db } from "@/lib/db";
4	import { GAME_FAMILIES, GAME_DISPLAY } from "@/lib/games";
5	import { currentPromo } from "@/lib/promotions";
6	import { firstMonthFreeAppliesTo } from "@/lib/promo-redemption";
7	import { annualDiscountPct } from "@/lib/annual-discount";
8	import { backupPlusMonthlyCents } from "@/lib/backup-upgrade";
9	import { extraDiskPerGbCents } from "@/lib/disk-expand";
10	import { planIntroMonthlyCents } from "@/lib/intro-pricing";
11	import { currentUser } from "@/lib/auth";
12	import { partnerPreviewForCode, partnerPreviewForUser } from "@/lib/partner-pricing";
13	import { AmbientField } from "@/components/marketing/AmbientField";
14	import { ReviewBadges } from "@/components/marketing/ReviewBadges";
15	import { POPULAR_TLDS } from "@/components/marketing/tlds";
16	import { ProductJsonLd, FaqJsonLd } from "@/components/marketing/StructuredData";
17	import {
18	  PricingExplorer,
19	  type ExplorerPlan,
20	  type ExplorerGameFamily,
21	  type ProductId,
22	} from "@/components/marketing/PricingExplorer";
23	
24	export const dynamic = "force-dynamic";
25	
26	export const metadata: Metadata = {
27	  title: "Pricing",
28	  description:
29	    "One place to compare every Nxeon product — Cloud VPS, game servers, shared web hosting, business email and domains. Live catalogue prices, monthly billing, no lock-in.",
30	  alternates: { canonical: "/pricing" },
31	};
32	
33	/* Deploy CTA target — the same href the previous pricing page's plan CTAs used. */
34	const DEPLOY_HREF = "/register";
35	const DOMAINS_HREF = "/domains";
36	
37	function gb(mb: number): string {
38	  return `${(mb / 1024).toFixed(mb % 1024 ? 1 : 0)} GB`;
39	}
40	/** Base MONTHLY price for a plan. VPS/Hosting store a monthly `priceCents`; Email &
41	 *  Game store it per `termMonths`, so normalise to a per-month figure. All display
42	 *  math downstream runs THIS through termPriceCents — the formula checkout charges. */
43	function monthlyOf(p: { priceCents: number; termMonths?: number }): number {
44	  const t = p.termMonths ?? 1;
45	  return t > 1 ? Math.round(p.priceCents / t) : p.priceCents;
46	}
47	
48	const INCLUDED: Record<ProductId, string[]> = {
49	  vps: ["Full root access", "Dedicated IPv4", "NVMe SSD", "DDoS protection", "Auto backups", "1-click reinstall"],
50	  game: ["DDoS protection", "Full control panel", "Instant deploy", "Game file manager", "Custom jar support"],
51	  hosting: ["Free SSL", "1-click WordPress", "Free migration", "cPanel included", "DDoS protection"],
52	  email: ["Webmail + IMAP/SMTP", "Spam & virus filtering", "Shared calendars & contacts", "Automatic MX/SPF setup"],
53	  domains: ["Free WhoisGuard privacy", "Full DNS management", "One-click VPS pointing", "Auto-renew"],
54	};
55	
56	const FAQ = [
57	  { q: "How does billing work across products?", a: "Every Nxeon product — VPS, game servers, shared hosting, business email and domains — is prepaid from your wallet balance, monthly by default. VPS also offers optional annual and multi-year terms at a discount. Whatever term you choose, services auto-renew at exactly that same price — the price you sign up at is the price you renew at — and nothing locks you in: cancel anytime and billing stops at the end of the current period." },
58	  { q: "Is the first month really free?", a: "On shared web hosting, yes — your first month is on us, then the plan renews at exactly the regular monthly price you see. The free-month offer applies to shared hosting only; VPS, game servers, business email and domains bill their regular price from month one." },
59	  { q: "Are the prices shown what I actually pay?", a: "Yes. Every price on this page is read live from the same catalogue the checkout charges from, so the number you see is the number you pay. Domain extensions show an indicative starting price — search a name for the exact live figure." },
60	];
61	
62	export default async function PricingPage() {
63	  // Every product line's prices, read LIVE from the catalogue. Nothing below is
64	  // hard-coded; a catalogue edit or deactivation propagates here automatically.
65	  const [vpsPlans, hostingPlans, emailPlans, gamePlans] = await Promise.all([
66	    db.plan.findMany({ where: { active: true }, orderBy: { sortOrder: "asc" } }),
67	    db.hostingPlan.findMany({ where: { active: true }, orderBy: [{ sortOrder: "asc" }, { priceCents: "asc" }] }),
68	    db.emailPlan.findMany({ where: { active: true }, orderBy: [{ sortOrder: "asc" }, { priceCents: "asc" }] }),
69	    db.gamePlan.findMany({ where: { active: true }, orderBy: [{ sortOrder: "asc" }, { priceCents: "asc" }] }),
70	  ]);
71	
72	  // The REAL, live annual discount + add-on prices (admin settings) — never
73	  // marketing constants. These are the SAME figures lib/order.ts bills, so the
74	  // add-on builder's "your build" total is displayed === charged.
75	  const [annualPct, backupPlusCents, extraDiskGbCents] = await Promise.all([
76	    annualDiscountPct(),
77	    backupPlusMonthlyCents(),
78	    extraDiskPerGbCents(),
79	  ]);
80	
81	  // Promo copy from the single source of truth — surfaced ONLY where the owner
82	  // scoped it (shared web hosting) via firstMonthFreeAppliesTo("HOSTING"). It is
83	  // passed as a nullable label so the badge cannot render on any other product.
84	  const hostingPromoLabel = firstMonthFreeAppliesTo("HOSTING") ? currentPromo(new Date()).label : null;
85	
86	  // CREATOR PARTNER PROGRAM: this must be visible BEFORE the customer's first
87	  // purchase (the owner's own requirement), including on this public pricing
88	  // page, before they've even registered. Two cases:
89	  //  - Signed in and already attached: read the REAL attachment (permanent,
90	  //    survives the cookie expiring) and show their actual tier (50%/10%).
91	  //  - Anonymous but carrying a valid `nxeon_ref` cookie for an ACTIVE partner
92	  //    code: they have no attachment yet (that's created at registration), so
93	  //    this is always framed as the 50% first-purchase preview.
94	  // Neither path touches per-order pricing (VPS/game quotes resolve their own,
95	  // real tier server-side) — this is messaging only, ahead of checkout.
96	  const jar = await cookies();
97	  const signedInUser = await currentUser();
98	  let partnerBanner: string | null = null;
99	  if (signedInUser) {
100	    const preview = await partnerPreviewForUser(signedInUser.id);
101	    if (preview.active) {
102	      partnerBanner =
103	        preview.tier === "FIRST"
104	          ? `You'll get 50% off your first order with ${preview.partnerName} — any service except domains.`
105	          : `You get 10% off every order, forever, with ${preview.partnerName} — any service except domains.`;
106	    }
107	  } else {
108	    const refCode = jar.get("nxeon_ref")?.value;
109	    const preview = refCode ? await partnerPreviewForCode(refCode) : { active: false, partnerName: null };
110	    if (preview.active) {
111	      partnerBanner = `You'll get 50% off your first order with ${preview.partnerName} — any service except domains. Sign up to claim it.`;
112	    }
113	  }
114	
115	  // ── VPS: 4 tiers. Middle = "Most popular" (violet), last = "Best value" (cyan). ──
116	  const vps: ExplorerPlan[] = vpsPlans.map((p, i) => ({
117	    id: p.id,
118	    name: p.name,
119	    monthlyCents: monthlyOf(p),
120	    // Optional LOW intro price → the card shows "$intro first term, then $regular/mo".
121	    // Null (no intro set) leaves the card at the plain regular price, unchanged.
122	    introMonthlyCents: planIntroMonthlyCents(p),
123	    badge:
124	      vpsPlans.length >= 3 && i === Math.floor((vpsPlans.length - 1) / 2)
125	        ? "popular"
126	        : vpsPlans.length >= 3 && i === vpsPlans.length - 1
127	          ? "best"
128	          : undefined,
129	    specs: [
130	      { label: "CPU", value: `${p.cpuCores} vCPU` },
131	      { label: "RAM", value: gb(p.ramMB) },
132	      { label: "Storage", value: `${p.diskGB} GB NVMe` },
133	      { label: "Bandwidth", value: `${p.bandwidthTB} TB` },
134	    ],
135	    href: DEPLOY_HREF,
136	  }));
137	
138	  // ── Hosting: featured tier gets the violet "Most popular" badge. ──
139	  const hosting: ExplorerPlan[] = hostingPlans.map((p, i) => ({
140	    id: p.id,
141	    name: p.name,
